      "entryType": "HAZARD",
      "name": "Fireball Rune",
      "level": 5,
      "rarity": "common",
      "size": "medium",
      "traits": [
        "fire",
        "magical",
        "trap"
      ],
      "description": "An invisible rune creates an invisible, spherical magical sensor with a 20-foot radius.",
      "armorClass": 0,
